    function generateRecommendation() {
        const concern = document.querySelector('input[name="concern"]:checked').value;
        const frequency = document.querySelector('input[name="frequency"]:checked').value;
        let text = "";

        if (frequency === 'Daily') {
            text = "Since you are feeling this way daily, we highly recommend connecting with a **Professional Therapist** for structured support. We also suggest trying our **Daily Challenges** to build small positive habits.";
        } else if (concern === 'Loneliness') {
            text = "We recommend joining our **Group Sessions** to connect with others who share similar experiences. You might also find our **Community Q&A** helpful.";
        } else {
            text = "Based on your answers, speaking with a **Volunteer Listener** could be very helpful. You can also explore our **Resource Library** for self-help guides on " + concern + ".";
        }

        document.getElementById('recommendationText').innerHTML = text;
    }

